SELECT CASE WHEN monthly_fee >= 186 THEN 'LARGE' ELSE 'SMALL' END AS monthly_fee_tier, APPROX_PERCENTILE(monthly_fee, 0.95) AS monthly_fee_p95, MAX(monthly_fee) AS max_monthly_fee, APPROX_PERCENTILE(monthly_fee, 0.9) AS monthly_fee_p90, SUM(CASE WHEN status = 'CANCELLED' THEN monthly_fee ELSE 0 END) AS cancelled_monthly_fee, SUM(monthly_fee) FILTER (WHERE plan = 'premium') AS premium_total_monthly_fee, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM subscriptions GROUP BY CASE WHEN monthly_fee >= 186 THEN 'LARGE' ELSE 'SMALL' END ORDER BY monthly_fee_p90 DESC NULLS FIRST;
